css:
.kagsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20303f;
    background: linear-gradient(180deg, #eef2f6 0%, #e3e9f0 100%);
    border-radius: 16px;
}

.kagsim-container * {
    box-sizing: border-box;
}

.kagsim-header {
    position: relative;
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1f2d3d 0%, #2c4b69 60%, #34566f 100%);
    color: #f4f8fb;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #16222e;
    box-shadow: 0 12px 30px rgba(31, 45, 61, 0.35);
    overflow: hidden;
}

.kagsim-header::before {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 5px;
    background: repeating-linear-gradient(90deg, #e8842b 0 22px, #1f2d3d 22px 30px);
    opacity: 0.85;
}

.kagsim-header h1 {
    margin: 10px 0 10px;
    font-size: 2.25rem;
    font-weight: 800;
    letter-spacing: -0.4px;
    color: #ffffff;
}

.kagsim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffb86b;
    background: rgba(232, 132, 43, 0.16);
    border: 1px solid rgba(232, 132, 43, 0.42);
    padding: 5px 14px;
    border-radius: 4px;
}

.kagsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cdd9e4;
}

.kagsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.95rem;
    font-weight: 600;
    color: #4a5d6f;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.kagsim-period-counter #currentDay,
.kagsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #c96a16;
}

.kagsim-round-name {
    background: #1f2d3d;
    color: #ffb86b;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.8rem;
    font-weight: 700;
    margin-left: 4px;
}

.kagsim-clock {
    margin-left: auto;
    font-size: 0.8rem;
    font-weight: 700;
    color: #b5470f;
    background: rgba(232, 132, 43, 0.14);
    border: 1px solid rgba(232, 132, 43, 0.38);
    padding: 4px 12px;
    border-radius: 4px;
}

.kagsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.kagsim-status-card {
    background: #ffffff;
    border-radius: 10px;
    padding: 16px 16px 14px;
    border: 1px solid #d4dde6;
    box-shadow: 0 5px 14px rgba(31, 45, 61, 0.10);
    border-left: 5px solid #2c4b69;
}

.kagsim-card-profit { border-left-color: #1f8a5b; }
.kagsim-card-retention { border-left-color: #2c6fb0; }
.kagsim-card-sow { border-left-color: #e8842b; }
.kagsim-card-cts { border-left-color: #6b54b8; }

.kagsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7d8f;
}

.kagsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.08;
    margin: 4px 0 2px;
    color: #1f2d3d;
    font-variant-numeric: tabular-nums;
}

.kagsim-card-profit .kagsim-value { color: #1f8a5b; }
.kagsim-card-retention .kagsim-value { color: #2c6fb0; }
.kagsim-card-sow .kagsim-value { color: #c96a16; }
.kagsim-card-cts .kagsim-value { color: #6b54b8; }

.kagsim-sublabel {
    font-size: 0.75rem;
    color: #7a8b9b;
    line-height: 1.35;
}

.kagsim-profit-negative .kagsim-value { color: #d83a2f; }
.kagsim-profit-positive .kagsim-value { color: #1f8a5b; }

.kagsim-cts-high { border-left-color: #d83a2f; }
.kagsim-cts-high .kagsim-value { color: #d83a2f; }
.kagsim-cts-low { border-left-color: #1f8a5b; }
.kagsim-cts-low .kagsim-value { color: #1f8a5b; }

.kagsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f2d3d;
    border: 1px solid #16222e;
    color: #dce6ef;
    padding: 11px 18px;
    border-radius: 8px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.kagsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ffb86b;
    font-variant-numeric: tabular-nums;
}

.kagsim-budget-over #budgetDisplay {
    color: #ff7a6b;
}

.kagsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #e8842b;
    border-radius: 10px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 5px 14px rgba(31, 45, 61, 0.10);
}

.kagsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.kagsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f2d3d;
    margin-bottom: 6px;
}

.kagsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4b5c;
}

.kagsim-briefing-text strong { color: #b5470f; }
.kagsim-briefing-text em { color: #2c6fb0; font-style: italic; }

.kagsim-controls {
    background: #ffffff;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d4dde6;
    box-shadow: 0 5px 14px rgba(31, 45, 61, 0.10);
}

.kagsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f2d3d;
    border-bottom: 2px solid #e3e9f0;
    padding-bottom: 8px;
}

.kagsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c3e50;
    margin: 14px 0 6px;
}

.kagsim-container select,
.kagsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c2cedb;
    border-radius: 7px;
    font-size: 0.92rem;
    background-color: #f7fafc;
    color: #1f2d3d;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.kagsim-container select:focus,
.kagsim-container input[type="number"]:focus {
    outline: none;
    border-color: #e8842b;
    box-shadow: 0 0 0 3px rgba(232, 132, 43, 0.18);
}

.kagsim-container select option {
    background-color: #ffffff;
    color: #1f2d3d;
}

.kagsim-hint {
    font-size: 0.8rem;
    color: #7a8b9b;
    margin-top: 6px;
    line-height: 1.45;
    border-left: 3px solid #d4dde6;
    padding-left: 10px;
}

.kagsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.kagsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f4f7fa;
    border: 1px solid #d8e1ea;
    border-radius: 7px;
    padding: 8px 12px;
}

.kagsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3a4b5c;
}

.kagsim-alloc-row input[type="number"] {
    width: 88px;
    flex: 0 0 88px;
}

.kagsim-alloc-readout {
    font-size: 0.9rem;
    font-weight: 700;
    color: #4a5d6f;
    margin-top: 8px;
}

.kagsim-alloc-readout span:nth-child(2) {
    color: #c96a16;
    font-weight: 800;
}

.kagsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.kagsim-container .btn-primary {
    background: linear-gradient(135deg, #c96a16 0%, #e8842b 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 7px;
    box-shadow: 0 8px 18px rgba(201, 106, 22, 0.32);
}

.kagsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.kagsim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c2cedb;
    color: #4a5d6f;
    background: transparent;
}

.kagsim-coach {
    background: linear-gradient(135deg, #243646 0%, #2c4b69 100%);
    color: #e3ecf3;
    border: 1px solid #16222e;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(31, 45, 61, 0.22);
}

.kagsim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffb86b;
    margin-bottom: 8px;
}

.kagsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.kagsim-coach-body strong { color: #ffb86b; }
.kagsim-coach-body em { color: #8fc7ff; font-style: italic; }

.kagsim-history,
.kagsim-chart {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d4dde6;
    box-shadow: 0 5px 14px rgba(31, 45, 61, 0.10);
}

.kagsim-history h3,
.kagsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f2d3d;
}

.kagsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4b5c;
}

.kagsim-container table#usfHistoryTable th {
    background: #1f2d3d;
    color: #ffb86b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #16222e;
}

.kagsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e3e9f0;
    color: #3a4b5c;
}

.kagsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f4f7fa;
}

.kagsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .kagsim-container {
        padding: 14px;
    }
    .kagsim-header h1 {
        font-size: 1.65rem;
    }
    .kagsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .kagsim-value {
        font-size: 2rem;
    }
    .kagsim-clock {
        margin-left: 0;
    }
    .kagsim-period-counter {
        font-size: 0.86rem;
    }
    .kagsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .kagsim-alloc-row {
        flex-wrap: wrap;
    }
    .kagsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .kagsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.kagsim-cm { background:#f6f9fb; color:#132029; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.kagsim-cm-head { text-align:center; border-bottom:1px solid #dbe4ea; padding-bottom:14px; margin-bottom:16px; }
.kagsim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#586974; font-weight:700; }
.kagsim-cm-scorewrap { margin:8px 0 2px; }
.kagsim-cm-score { font-size:52px; font-weight:800; color:#1f8a5b; line-height:1; }
.kagsim-cm-score-max { font-size:20px; color:#84939c; font-weight:600; }
.kagsim-cm-grade { font-size:19px; font-weight:700; color:#132029; margin-top:4px; }
.kagsim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.kagsim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.kagsim-cm-met { background:#d3f0e1; color:#0f6b45; }
.kagsim-cm-fail { background:#fce0dc; color:#a4322a; }
.kagsim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.kagsim-cm-metric { background:#eaf0f4; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.kagsim-cm-metric-val { font-size:22px; font-weight:800; color:#132029; }
.kagsim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#586974; margin-top:3px; }
.kagsim-cm-insights { background:#eaf0f4; border-radius:10px; padding:14px 18px; }
.kagsim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#586974; font-weight:700; margin-bottom:8px; }
.kagsim-cm-insights ul { margin:0; padding-left:18px; }
.kagsim-cm-insights li { font-size:14px; line-height:1.5; color:#2b3841; margin-bottom:7px; }

