(function() {
    'use strict';

    class KeyAccountAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Key Account Gambit`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Liant Composants, France / EUR).
            this.BASELINE_PROFIT = 11.5;    // EUR M portfolio profit after cost-to-serve at start
            this.BUDGET_CAP = 1.5;          // EUR 1.5M fixed commercial budget — cannot grow
            this.SMALL_LEAK = 1.1;          // EUR 1.1M/yr lost servicing 40 small accounts at a uniform tier
            this.MIDTIER_VALUE = 9.5;       // EUR 9.5M of high-margin, under-served mid-tier accounts
            this.ANCHOR_REVENUE = 13;       // EUR 13M/yr anchor (Aérospatiale), 18% of revenue
            this.DUALSOURCE_RISK = 5.2;     // ≈EUR 5.2M revenue at risk if 40% dual-sources
            this.BLANKET_DISCOUNT_COST = 2; // ≈EUR 2M margin vaporised by a broad 9% cut
            this.AI_CLEANUP = 0.09;         // EUR 90k data cleanup to run one module well

            // Per-round commercial spend drawn from the EUR 1.5M cap.
            this.TIER_COST = { premium: 0.45, growth: 0.20, selfserve: 0.05, transactional: 0.04, growth2: 0.30, strategic: 0.50 };

            // Concept truths.
            this.TRUE_LENS = `valuepotential`;
            this.TRUE_DEFENSE = `volume`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    profit: this.BASELINE_PROFIT, // EUR M account profitability after cost-to-serve
                    retention: 70,                // strategic & mid-tier accounts held (0–100)
                    sow: 35,                      // share-of-wallet at top accounts (%)
                    cts: 100,                     // cost-to-serve index vs baseline 100 (lower leaner)
                    budgetUsed: 0,                // EUR M of the 1.5M commercial budget committed
                    leakRecovered: false,
                    overInvestedAnchor: false,
                    blanketDiscount: false,
                    aiSprawl: false,
                    profitHistory: [this.BASELINE_PROFIT],
                    retentionHistory: [70],
                    sowHistory: [35],
                    ctsHistory: [100],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the CLASSIC WRONG strategy
                // (revenue lens, 55% effort on top 3, uniform premium, AI sprawl,
                // blanket discount, new-logo reflex) — a click-through must not auto-win.
                state.decisions = {
                    lens: `revenue`,
                    ctsView: `skip`,
                    diagnosis: `topfine`,
                    effortAnchor: 55,
                    effortMid: 25,
                    effortTail: 15,
                    effortSmall: 5,
                    smallTier: `premium`,
                    midTier: `transactional`,
                    ai: `all`,
                    defense: `blanket`,
                    growth: `newlogos`,
                    sowTarget: 50,
                    rhythm: `none`,
                    underserve: `none`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ln = document.getElementById(`lensInput`);
                const cv = document.getElementById(`ctsViewInput`);
                const dg = document.getElementById(`diagnosisInput`);
                if (ln) decisions.lens = ln.value;
                if (cv) decisions.ctsView = cv.value;
                if (dg) decisions.diagnosis = dg.value;
            } else if (round === 2) {
                const a = document.getElementById(`effortAnchorInput`);
                const m = document.getElementById(`effortMidInput`);
                const t = document.getElementById(`effortTailInput`);
                const s = document.getElementById(`effortSmallInput`);
                const st = document.getElementById(`smallTierInput`);
                const mt = document.getElementById(`midTierInput`);
                if (a) decisions.effortAnchor = parseFloat(a.value);
                if (m) decisions.effortMid = parseFloat(m.value);
                if (t) decisions.effortTail = parseFloat(t.value);
                if (s) decisions.effortSmall = parseFloat(s.value);
                if (st) decisions.smallTier = st.value;
                if (mt) decisions.midTier = mt.value;
                const parts = [decisions.effortAnchor, decisions.effortMid, decisions.effortTail, decisions.effortSmall];
                if (parts.some((v) => !Number.isFinite(v) || v < 0 || v > 100)) {
                    warn(`warn_effort_value`); return false;
                }
                const total = decisions.effortAnchor + decisions.effortMid + decisions.effortTail + decisions.effortSmall;
                if (Math.abs(total - 100) > 0.001) {
                    warn(`warn_effort_total`); return false;
                }
            } else if (round === 3) {
                const ai = document.getElementById(`aiInput`);
                const df = document.getElementById(`defenseInput`);
                const gr = document.getElementById(`growthInput`);
                if (ai) decisions.ai = ai.value;
                if (df) decisions.defense = df.value;
                if (gr) decisions.growth = gr.value;
            } else if (round === 4) {
                const st = document.getElementById(`sowTargetInput`);
                const rh = document.getElementById(`rhythmInput`);
                const us = document.getElementById(`underserveInput`);
                const cv = document.getElementById(`convictionInput`);
                if (st) decisions.sowTarget = parseFloat(st.value);
                if (rh) decisions.rhythm = rh.value;
                if (us) decisions.underserve = us.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.sowTarget) || decisions.sowTarget < 35 || decisions.sowTarget > 80) {
                    warn(`warn_sow_range`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let profitDelta = 0, retentionDelta = 0, sowDelta = 0, ctsDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the portfolio. Revenue is a misleading lens (Common Error 1, Key Concept 2).
                switch (d.lens) {
                    case `valuepotential`: retentionDelta += 4; coachKey = `coach_r1_valuepotential`; break;
                    case `margin`: retentionDelta += 1; coachKey = `coach_r1_margin`; break;
                    case `revenue`: retentionDelta -= 3; ctsDelta += 2; coachKey = `coach_r1_revenue`; break;
                }
                // Cost-to-serve must be made visible or every later allocation is guesswork (Key Concept 3).
                switch (d.ctsView) {
                    case `full`: profitDelta += 0.3; ctsDelta -= 3; coachKey = (d.lens === `valuepotential`) ? `coach_r1_sharp` : coachKey; break;
                    case `toponly`: profitDelta += 0.1; break;
                    case `skip`: ctsDelta += 3; coachKey = `coach_r1_skipcts`; break;
                }
                // The one-line diagnosis.
                switch (d.diagnosis) {
                    case `trapped`: retentionDelta += 3; break;
                    case `smallcut`: retentionDelta -= 1; break;
                    case `topfine`: retentionDelta -= 4; ctsDelta += 2; coachKey = `coach_r1_topfine`; break;
                }
                summaryKey = (d.lens === `valuepotential` && d.ctsView === `full` && d.diagnosis === `trapped`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate effort + design tiers. Effort is the scarcest resource (Facilitator tree 1).
                const anchor = d.effortAnchor, mid = d.effortMid, small = d.effortSmall;

                // Pulling effort off the top 3 toward the high-margin mid-tier is the core KAM move.
                if (anchor >= 50) { retentionDelta += 3; sowDelta += 1; ctsDelta += 2; ds.overInvestedAnchor = true; coachKey = `coach_r2_anchorheavy`; }
                else if (anchor <= 35) { retentionDelta -= 2; }
                if (mid >= 30) { profitDelta += 0.8; sowDelta += 4; retentionDelta += 4; coachKey = `coach_r2_midfund`; }
                else if (mid <= 15) { retentionDelta -= 4; coachKey = `coach_r2_midstarve`; }
                if (small >= 20) { profitDelta -= 0.4; ctsDelta += 4; coachKey = `coach_r2_smalleffort`; }

                // Service-tier design — the cost-to-serve lever (Common Error 2, Facilitator tree 2).
                spend += this.TIER_COST[d.smallTier] + this.TIER_COST[d.midTier];
                switch (d.smallTier) {
                    case `selfserve`: profitDelta += this.SMALL_LEAK; ctsDelta -= 14; ds.leakRecovered = true; coachKey = `coach_r2_selfserve`; break;
                    case `growth`: profitDelta += this.SMALL_LEAK * 0.45; ctsDelta -= 6; break;
                    case `premium`: ctsDelta += 6; retentionDelta -= 1; coachKey = `coach_r2_uniform`; break;
                }
                switch (d.midTier) {
                    case `growth2`: profitDelta += 0.9; sowDelta += 3; retentionDelta += 3; ctsDelta += 3; break;
                    case `strategic`: profitDelta -= 0.3; ctsDelta += 9; retentionDelta += 2; coachKey = `coach_r2_overserve`; break;
                    case `transactional`: retentionDelta -= 3; sowDelta -= 1; coachKey = `coach_r2_midstarve`; break;
                }
                summaryKey = (d.smallTier === `selfserve` && d.midTier === `growth2` && anchor <= 45 && mid >= 30) ? `sum_r2_good` :
                             (d.smallTier === `premium` ? `sum_r2_uniform` : `sum_r2_weak`);
            } else if (round === 3) {
                // Choose ONE AI module + defend the anchor (Common Errors 3 & 4, Facilitator trees 3,4,6).
                if (d.ai === `all`) {
                    // AI sprawl on immature data: three mediocre models, EUR 90k cleanup wasted thrice over.
                    spend += this.AI_CLEANUP * 3;
                    retentionDelta -= 2; sowDelta -= 1; ds.aiSprawl = true; coachKey = `coach_r3_aisprawl`;
                } else {
                    spend += this.AI_CLEANUP;
                    switch (d.ai) {
                        case `churn`: retentionDelta += 6; coachKey = `coach_r3_churn`; break;
                        case `scoring`: profitDelta += 0.5; ctsDelta -= 3; coachKey = `coach_r3_scoring`; break;
                        case `nba`: sowDelta += 5; profitDelta += 0.4; coachKey = `coach_r3_nba`; break;
                    }
                }

                // The Aérospatiale defense — every concession must buy something (Facilitator tree 3,6).
                switch (d.defense) {
                    case `volume`:
                        // Targeted discount tied to a volume commitment + engineer as paid service.
                        retentionDelta += 8; profitDelta -= 0.4; sowDelta += 2; coachKey = `coach_r3_volume`; break;
                    case `value`:
                        // Value reframe (TCO, reliability) holds price but risks some dual-sourcing.
                        retentionDelta += 4; profitDelta += 0.2; coachKey = `coach_r3_value`; break;
                    case `walkaway`:
                        // Accept 40% dual-source, keep the profitable 60%, redeploy the engineer.
                        retentionDelta += 2; profitDelta += 0.6; ctsDelta -= 2; coachKey = `coach_r3_walkaway`; break;
                    case `blanket`:
                        // Match 9% AND extend it across the book — vaporises ~EUR 2M for no commitment.
                        profitDelta -= this.BLANKET_DISCOUNT_COST; retentionDelta += 3; sowDelta -= 1; ds.blanketDiscount = true; coachKey = `coach_r3_blanket`; break;
                    case `cave`:
                        // Full 9% + free engineer, no strings — anchor now barely profitable after cost-to-serve.
                        profitDelta -= 1.3; retentionDelta += 6; ctsDelta += 8; ds.overInvestedAnchor = true; coachKey = `coach_r3_cave`; break;
                }

                // Growth lever: share-of-wallet inside existing accounts beats new logos (Common Error 5, tree 5).
                switch (d.growth) {
                    case `sow`: sowDelta += 7; profitDelta += 0.5; coachKey = (d.defense === `volume`) ? `coach_r3_sharp` : coachKey; break;
                    case `mix`: sowDelta += 2; profitDelta -= 0.2; break;
                    case `newlogos`: sowDelta -= 2; profitDelta -= 0.6; ctsDelta += 3; coachKey = `coach_r3_newlogos`; break;
                }
                summaryKey = ((d.defense === `volume` || d.defense === `value` || d.defense === `walkaway`) && d.ai !== `all` && d.growth === `sow`) ? `sum_r3_good` :
                             (d.defense === `blanket` ? `sum_r3_blanket` : (d.ai === `all` ? `sum_r3_sprawl` : `sum_r3_weak`));
            } else if (round === 4) {
                // Recover & set the operating rhythm.
                // A credible, reachable share-of-wallet target beats a heroic over-promise.
                if (d.sowTarget >= 45 && d.sowTarget <= 58) { sowDelta += 5; retentionDelta += 3; coachKey = `coach_r4_crediblesow`; }
                else if (d.sowTarget > 65) { retentionDelta -= 3; coachKey = `coach_r4_overpromise`; }
                else { sowDelta += 1; }

                switch (d.rhythm) {
                    case `quarterly`: profitDelta += 0.6; ctsDelta -= 5; retentionDelta += 4; coachKey = `coach_r4_rhythm`; break;
                    case `annual`: ctsDelta += 1; break;
                    case `none`: retentionDelta -= 4; ctsDelta += 4; coachKey = `coach_r4_norhythm`; break;
                }
                switch (d.underserve) {
                    case `small`: profitDelta += 0.4; ctsDelta -= 4; if (!ds.leakRecovered) { profitDelta += 0.5; ds.leakRecovered = true; } coachKey = (d.rhythm === `quarterly`) ? `coach_r4_disciplined` : coachKey; break;
                    case `midtier`: profitDelta -= 0.3; sowDelta -= 3; retentionDelta -= 2; coachKey = `coach_r4_wrongunderserve`; break;
                    case `none`: ctsDelta += 5; profitDelta -= 0.3; coachKey = `coach_r4_nounderserve`; break;
                }
                if (d.conviction >= 60) { retentionDelta += 4; }
                else if (d.conviction <= 25) { retentionDelta -= 4; }
                summaryKey = (d.rhythm === `quarterly` && d.underserve === `small` && d.sowTarget <= 58) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting against the fixed EUR 1.5M commercial budget.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;
            // Over-committing the fixed budget is itself a penalty (it cannot grow this year).
            if (ds.budgetUsed > this.BUDGET_CAP + 0.001) {
                const over = ds.budgetUsed - this.BUDGET_CAP;
                profitDelta -= over * 1.5;
                ctsDelta += over * 6;
                if (coachKey === `coach_default`) coachKey = `coach_overbudget`;
            }

            // Apply deltas. Profit is EUR M; retention/cts are indices (cts can exceed 100 when bloated).
            ds.profit = Math.round((ds.profit + profitDelta) * 10) / 10;
            ds.retention = Math.max(0, Math.min(100, Math.round(ds.retention + retentionDelta)));
            ds.sow = Math.max(0, Math.min(100, Math.round(ds.sow + sowDelta)));
            ds.cts = Math.max(40, Math.min(160, Math.round(ds.cts + ctsDelta)));

            ds.profitHistory.push(ds.profit);
            ds.retentionHistory.push(ds.retention);
            ds.sowHistory.push(ds.sow);
            ds.ctsHistory.push(ds.cts);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                profit: ds.profit,
                profitDelta: Math.round(profitDelta * 10) / 10,
                retention: ds.retention,
                retentionDelta: Math.round(retentionDelta),
                sow: ds.sow,
                sowDelta: Math.round(sowDelta),
                cts: ds.cts,
                ctsDelta: Math.round(ctsDelta),
                budgetUsed: ds.budgetUsed,
                leakRecovered: ds.leakRecovered,
                blanketDiscount: ds.blanketDiscount,
                aiSprawl: ds.aiSprawl,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware EUR: English "€11.5M" (symbol before), Spanish "11,5 M€" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M€`;
            }
            return `${sign}€${abs.toFixed(1)}M`;
        }

        _fmtBudget(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${abs.toFixed(2).replace(`.`, `,`)} M€`;
            }
            return `€${abs.toFixed(2)}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`profitDisplay`, `domainState.profit`, (v) => {
                const card = document.querySelector(`.kagsim-card-profit`);
                if (card) {
                    card.classList.toggle(`kagsim-profit-positive`, Number(v) >= self.BASELINE_PROFIT);
                    card.classList.toggle(`kagsim-profit-negative`, Number(v) < self.BASELINE_PROFIT - 0.05);
                }
                return self._fmtMoney(Number(v));
            });
            uiManager.bind(`retentionDisplay`, `domainState.retention`, (v) => Math.round(Number(v)));
            uiManager.bind(`sowDisplay`, `domainState.sow`, (v) => Math.round(Number(v)) + `%`);
            uiManager.bind(`ctsDisplay`, `domainState.cts`, (v) => {
                const card = document.querySelector(`.kagsim-card-cts`);
                if (card) {
                    card.classList.toggle(`kagsim-cts-high`, Number(v) >= 110);
                    card.classList.toggle(`kagsim-cts-low`, Number(v) <= 85);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.kagsim-budget-bar`);
                if (bar) bar.classList.toggle(`kagsim-budget-over`, Number(v) > self.BUDGET_CAP + 0.001);
                return self._fmtBudget(Number(v)) + ` / ` + self._fmtBudget(self.BUDGET_CAP);
            });

            // Effort-allocation live total (must hit 100%).
            const effortIds = [`effortAnchorInput`, `effortMidInput`, `effortTailInput`, `effortSmallInput`];
            const effortReadout = document.getElementById(`effortReadout`);
            const recompute = function() {
                let total = 0;
                effortIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (effortReadout) effortReadout.textContent = total;
                const bar = document.querySelector(`.kagsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - 100) > 0.001) ? `#d83a2f` : ``;
            };
            effortIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

