        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.retentionHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                kagChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.retentionHistory },
                        { data: ds.sowHistory },
                        { data: ds.ctsHistory },
                        { data: ds.profitHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const profit = ds.profit;
            const retention = Math.round(ds.retention);
            const sow = Math.round(ds.sow);
            const cts = Math.round(ds.cts);
            const profitScore = Math.max(-30, Math.min(40, (profit - this.BASELINE_PROFIT) * 12));
            const ctsScore = Math.max(0, Math.min(100, 200 - cts));
            return Math.round(
                Math.max(0, Math.min(100, 50 + profitScore)) * 0.34 +
                retention * 0.26 +
                sow * 0.20 +
                ctsScore * 0.20
            );
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const profit = ds.profit;
            const retention = Math.round(ds.retention);
            const sow = Math.round(ds.sow);
            const cts = Math.round(ds.cts);

            // Composite: profit lift vs baseline, retention, share-of-wallet, and a leaner cost-to-serve.
            const composite = this._composite(ds);

            const profitable = profit >= this.BASELINE_PROFIT;
            const retained = retention >= 70;
            const grew = sow >= 45;
            const lean = cts <= 95;
            const bledMargin = ds.blanketDiscount || profit <= this.BASELINE_PROFIT - 1.5;

            let performanceKey = `grade_adrift`;
            if (profitable && retained && grew && lean && composite >= 78) performanceKey = `grade_mastered`;
            else if (profitable && retained && grew) performanceKey = `grade_anchorheld`;
            else if (bledMargin) performanceKey = `grade_bled`;
            else if (!retained && retention <= 55) performanceKey = `grade_anchorlost`;
            else if (composite >= 58) performanceKey = `grade_mixed`;
            const met = profitable && retained && grew && lean && composite >= 78;
            const anchorLost = !retained && retention <= 55;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (profitable && retained && grew && lean) insights.push(window.mySimulation.t(`insight_mastered`));
            else if (bledMargin) insights.push(window.mySimulation.t(`insight_bled`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!ds.leakRecovered) insights.push(window.mySimulation.t(`insight_leak`));
            if (sow >= 50) insights.push(window.mySimulation.t(`insight_sow_strong`));
            else if (sow < 38) insights.push(window.mySimulation.t(`insight_sow_flat`));
            if (ds.aiSprawl) insights.push(window.mySimulation.t(`insight_aisprawl`));
            if (ds.overInvestedAnchor && profit < this.BASELINE_PROFIT) insights.push(window.mySimulation.t(`insight_anchorover`));
            if (cts <= 85) insights.push(window.mySimulation.t(`insight_lean`));

            return {
                profit: profit,
                retention: retention,
                sow: sow,
                cts: cts,
                profitable: profitable,
                retained: retained,
                grew: grew,
                lean: lean,
                bledMargin: bledMargin,
                anchorLost: anchorLost,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="kagsim-cm-badge ` + (s.met ? `kagsim-cm-met` : `kagsim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.bledMargin) badges.push(`<span class="kagsim-cm-badge kagsim-cm-fail">` + t(`cm_fail_bled`) + `</span>`);
            if (s.anchorLost) badges.push(`<span class="kagsim-cm-badge kagsim-cm-fail">` + t(`cm_fail_anchor`) + `</span>`);
            if (s.grew === false) badges.push(`<span class="kagsim-cm-badge kagsim-cm-fail">` + t(`cm_fail_sow`) + `</span>`);
            const kpi = (label, val) => `<div class="kagsim-cm-metric"><div class="kagsim-cm-metric-val">` + val + `</div><div class="kagsim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_profit`), `€` + (s.profit != null ? s.profit : 0) + `M`) + kpi(t(`cm_retention`), (s.retention != null ? s.retention : 0) + `%`) + kpi(t(`cm_sow`), (s.sow != null ? s.sow : 0) + `%`) + kpi(t(`cm_cts`), (s.cts != null ? s.cts : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="kagsim-cm">`
                + `<div class="kagsim-cm-head"><div class="kagsim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="kagsim-cm-scorewrap"><span class="kagsim-cm-score">` + score + `</span><span class="kagsim-cm-score-max">/100</span></div>`
                + `<div class="kagsim-cm-grade">` + grade + `</div>`
                + `<div class="kagsim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="kagsim-cm-metrics">` + kpis + `</div>`
                + `<div class="kagsim-cm-insights"><div class="kagsim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.blanketDiscount) return window.mySimulation.t(`hint_blanket`);
            if (ds.aiSprawl) return window.mySimulation.t(`hint_aisprawl`);
            if (!ds.leakRecovered && state.currentPeriod >= 2) return window.mySimulation.t(`hint_leak`);
            if (ds.cts >= 115) return window.mySimulation.t(`hint_cts`);
            if (state.currentPeriod >= 3 && ds.sow < 38) return window.mySimulation.t(`hint_sow`);
            if (ds.profit >= this.BASELINE_PROFIT + 1 && ds.retention >= 75 && ds.sow >= 48) return window.mySimulation.t(`hint_strong`);
            return null;
        }

